-- stochastic-processes implementation for MarkovChain
-- Assumptions: stochastic increments use the specified time step; physical SDE parameters use SI units and random draws are supplied or generated by the documented stream.

local Module = {}
function Module.Step(current,transition,uniform)
    assert(current>=1 and current<=#transition,"current state out of range"); assert(uniform>=0 and uniform<1,"uniform variate must be in [0,1)")
    local cumulative=0
    for nextState=1,#transition[current] do
        local probability=transition[current][nextState]; assert(probability>=0 and probability<=1,"transition probability outside [0,1]"); cumulative+=probability
        if uniform<cumulative then return nextState end
    end
    assert(math.abs(cumulative-1)<1e-8,"transition row must sum to one")
    return #transition[current]
end

return Module
